package cn.huankan.event;
import java.util.*;import java.time.*;import java.math.*;import cn.huankan.evidence.EvidenceService;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.fasterxml.jackson.databind.ObjectMapper;
@Service public class MacroResearchService {
 private final JdbcTemplate db;private final ObjectMapper json;public MacroResearchService(JdbcTemplate d,ObjectMapper j){db=d;json=j;}private String encode(Object x){try{return json.writeValueAsString(x);}catch(Exception e){throw new IllegalArgumentException("研究快照编码失败");}}
 public Object catalog(){return db.queryForList("SELECT id,title,units,frequency,source_id FROM macro_series ORDER BY source_id,id");}
 @Transactional public Map<String,Object> analyze(String series,Instant asOf){if(series==null||!series.matches("[A-Z0-9._]{5,100}")||asOf==null||asOf.isAfter(Instant.now().plusSeconds(5)))throw new IllegalArgumentException("指标与证据截止时间无效");var meta=db.queryForMap("SELECT m.*,s.name publisher FROM macro_series m JOIN source_registry s ON s.id=m.source_id WHERE m.id=?",series);var rows=db.queryForList("SELECT DISTINCT ON(m.observation_date) m.*,r.raw_content,r.raw_content_hash,r.source_url,r.published_at,r.collected_at,f.id fact_id,f.fields FROM macro_observation m JOIN raw_evidence r ON r.id=m.evidence_id JOIN fact_candidate f ON f.observation_id=m.evidence_id JOIN source_license l ON l.source_id=r.source_id WHERE m.series_id=? AND r.collected_at<=? AND f.created_at<=? AND (r.published_at IS NULL OR r.published_at<=?) AND l.status='APPROVED' AND l.storage_allowed AND l.display_allowed AND (l.valid_until IS NULL OR l.valid_until>now()) AND COALESCE((SELECT decision FROM fact_review v WHERE v.fact_id=f.id AND v.created_at<=? ORDER BY v.created_at DESC,v.id DESC LIMIT 1),f.verification_status) IN('FIELD_MATCHED','INDEPENDENT_SUPPORTED') ORDER BY m.observation_date DESC,m.version DESC LIMIT 60",series,java.sql.Timestamp.from(asOf),java.sql.Timestamp.from(asOf),java.sql.Timestamp.from(asOf),java.sql.Timestamp.from(asOf));if(rows.isEmpty())throw new IllegalArgumentException("证据截止前没有合格的实际观测");var inputs=new ArrayList<Map<String,Object>>();for(var row:rows){if(!EvidenceService.hash((byte[])row.get("raw_content")).equals(row.get("raw_content_hash")))throw new IllegalArgumentException("研究输入哈希失败");Map<String,Object> fields;try{fields=json.readValue(row.get("fields").toString(),Map.class);}catch(Exception e){throw new IllegalArgumentException("研究字段不完整");}var input=new LinkedHashMap<String,Object>();for(String key:List.of("evidence_id","fact_id","observation_date","value","version","observation_status","source_url","raw_content_hash","published_at","collected_at"))input.put(key,row.get(key));input.put("unit",fields.get("unit"));input.put("frequency",fields.get("frequency"));input.put("source_fields",fields);inputs.add(input);}var current=inputs.getFirst();var comparison=MacroComparison.compare(inputs);
 var report=new LinkedHashMap<String,Object>();report.put("title",meta.get("title"));report.put("fact_summary",comparison);report.put("official_source",Map.of("publisher",meta.get("publisher"),"url",current.get("source_url")));report.put("published_at",current.get("published_at"));report.put("key_numbers",comparison);report.put("history",Map.of("observations",inputs.size(),"source_vintage","未知：不能把本地取得版本当作源站历史vintage","interpretation","同序列同单位观测比较，不补造市场预期；月度指数数学变化不等同季调新闻增长率"));report.put("institutions",List.of(meta.get("publisher")));String rule=series.startsWith("EXR.")?"REFERENCE_FX":series.startsWith("FM.")?"POLICY":series.startsWith("CU")||series.startsWith("WP")?"INFLATION":"EMPLOYMENT";report.put("mechanism",switch(rule){case "INFLATION"->"物价指标可经购买力、政策利率预期与成本折算影响经济主体；方向需结合构成、季调口径与真实敞口";case "POLICY"->"政策利率可经融资成本、现金流折现及汇率预期传导；缺少市场预期不能宣称政策意外";case "REFERENCE_FX"->"参考汇率变化可影响外币收支折算；缺少合同及敞口不能确定企业盈亏";default->"就业水平与失业率可反映劳动力市场状态，可能关联收入、需求与政策预期；就业总人数不能等同新增非农就业";});report.put("possible_markets",List.of("条件性关联：利率和债券市场","条件性关联：外汇市场","条件性关联：权益估值与融资成本；未验证实际价格反应"));report.put("positive_hypotheses",List.of("只有实际成本降低、收入或现金流改善时，对应真实敞口主体才可能受益；目前未形成确定受益名单"));report.put("negative_hypotheses",List.of("成本或融资压力上升可能拖累对应敞口；未取得公司真实敞口时不作确定归因"));report.put("counter_evidence",List.of("相邻观测的变化不证明因果；尚无独立反向资料和市场验证，不能据此确认假设"));report.put("gaps",List.of("真实市场一致预期缺失","首次发布时间未知的序列无法复原公告时点","行情许可、企业敞口及真实业务关系不足"));report.put("watch_variables",List.of("后续同口径观测","原始值或脚注修订","官方政策公告","市场数据合法接入后的事件窗口"));report.put("validity",List.of("仅使用证据截止前实际取得的数据","单位、季调口径或值修订时应重算新快照","新的反向证据可能使假设失效"));report.put("market_status","待验证，没有生成行情、收益率或交易建议");UUID id=UUID.randomUUID();db.update("INSERT INTO research_input_snapshot(id,series_id,as_of,rule_id,rule_version,inputs,report) VALUES(?,?,?,?, '宏观同口径比较-1.2',?::jsonb,?::jsonb) ON CONFLICT DO NOTHING",id,series,java.sql.Timestamp.from(asOf),rule,encode(inputs),encode(report));return view(db.queryForMap("SELECT * FROM research_input_snapshot WHERE series_id=? AND as_of=? AND rule_id=? AND rule_version='宏观同口径比较-1.2'",series,java.sql.Timestamp.from(asOf),rule));}
 public Object history(int page){if(page<0||page>100000)throw new IllegalArgumentException("研究分页无效");var rows=db.queryForList("SELECT * FROM research_input_snapshot ORDER BY created_at DESC,id LIMIT 50 OFFSET ?",page*50);rows.forEach(this::view);return rows;}private Map<String,Object> view(Map<String,Object> row){try{for(String key:List.of("inputs","report"))row.put(key,json.readTree(row.get(key).toString()));return row;}catch(Exception e){throw new IllegalArgumentException("研究快照结构异常");}}
}

